        instruction: { en: "Individually, research a current environmental news story from Brazil or your local area. Prepare a short presentation (2-3 minutes) to summarize the news using the learned vocabulary, phrasal verbs, and summarizing expressions. Be ready to answer questions.", pt: "Individualmente, pesquise uma notícia ambiental atual do Brasil ou de sua área local. Prepare uma apresentação curta (2-3 minutos) para resumir a notícia usando o vocabulário aprendido, os phrasal verbs e as expressões de resumo. Esteja pronto para responder a perguntas." },
        phrases: [{ en: "According to the recent report, deforestation has a significant impact on the Amazon ecosystem.", pt: "De acordo com o relatório recente, o desmatamento tem um impacto significativo no ecossistema amazônico." }, { en: "The main issue is that local communities often give up on conservation efforts without government support.", pt: "O principal problema é que as comunidades locais frequentemente desistem dos esforços de conservação sem apoio governamental." }, { en: "To sum up, we must work out new strategies for renewable energy and waste management.", pt: "Para resumir, devemos elaborar novas estratégias para energia renovável e gestão de resíduos." }],
        check: [
          { id: "i33c-ch1q1", prompt: { en: "What is the purpose of 'To sum up...'?", pt: "Qual é o propósito de 'To sum up...'?" }, options: ["To introduce new information.", "To present a problem.", "To conclude or summarize."], answer: "To conclude or summarize.", explanation: { en: "'To sum up' is used to bring a discussion or presentation to a conclusion.", pt: "'To sum up' é usado para encerrar uma discussão ou apresentação." } },
          { id: "i33c-ch1q2", prompt: { en: "If you say 'We cannot give up on protecting our climate,' what are you emphasizing?", pt: "Se você diz 'Não podemos desistir de proteger nosso clima', o que você está enfatizando?" }, options: ["The need to stop trying.", "The importance of persistence.", "The ease of the task."], answer: "The importance of persistence.", explanation: { en: "Not giving up highlights the need to continue efforts despite difficulties.", pt: "Não desistir destaca a necessidade de continuar os esforços apesar das dificuldades." } },
        ],
