      input: {
        kind: "reading",
        title: { en: "The Future of News", pt: "O Futuro das Notícias" },
        lines: [
          { en: "In today's fast-paced world, news consumption is constantly evolving. Traditional newspapers are facing challenges from online platforms. While print articles still have their loyal readers, digital news sources offer instant updates and multimedia content.", pt: "No mundo acelerado de hoje, o consumo de notícias está em constante evolução. Jornais tradicionais estão enfrentando desafios de plataformas online. Embora os artigos impressos ainda tenham seus leitores leais, as fontes de notícias digitais oferecem atualizações instantâneas e conteúdo multimídia." },
          { en: "Many people now prefer to get their daily headlines from social media or news apps. These platforms often provide a broader coverage of global topics. However, the reliability of the source is a growing concern, as opinion pieces can sometimes be presented as factual reports.", pt: "Muitas pessoas agora preferem obter suas manchetes diárias de mídias sociais ou aplicativos de notícias. Essas plataformas frequentemente fornecem uma cobertura mais ampla de tópicos globais. No entanto, a confiabilidade da fonte é uma preocupação crescente, pois artigos de opinião podem às vezes ser apresentados como reportagens factuais." },
          { en: "Journalists play a crucial role in verifying information, whether for a broadcast or an online article. Compared to the past, journalists today need to be even more diligent. They also face the challenge of engaging audiences who are used to quick information.", pt: "Jornalistas desempenham um papel crucial na verificação de informações, seja para uma transmissão ou um artigo online. Comparado ao passado, jornalistas hoje precisam ser ainda mais diligentes. Eles também enfrentam o desafio de engajar públicos que estão acostumados a informações rápidas." },
          { en: "Some news organizations are investing in long-form journalism and in-depth interviews to differentiate themselves. I'd recommend subscribing to a service that values thorough reporting over sensationalism. It's essential to stay informed, but also to be critical of what we read.", pt: "Algumas organizações de notícias estão investindo em jornalismo de formato longo e entrevistas aprofundadas para se diferenciar. Eu recomendaria assinar um serviço que valoriza a reportagem minuciosa em vez do sensacionalismo. É essencial se manter informado, mas também ser crítico em relação ao que lemos." },
        ],
        questions: [
          { id: "i35d-iq1", prompt: { en: "What is a main challenge for traditional newspapers?", pt: "Qual é um desafio principal para os jornais tradicionais?" }, options: ["Lack of loyal readers.", "Competition from online platforms.", "Difficulty in finding good journalists."], answer: "Competition from online platforms.", explanation: { en: "The text states that 'Traditional newspapers are facing challenges from online platforms'.", pt: "O texto afirma que 'Jornais tradicionais estão enfrentando desafios de plataformas online'." } },
          { id: "i35d-iq2", prompt: { en: "What does the author recommend for news consumption?", pt: "O que o autor recomenda para o consumo de notícias?" }, options: ["Subscribing to sensational news services.", "Relying only on social media headlines.", "Subscribing to services that value thorough reporting."], answer: "Subscribing to services that value thorough reporting.", explanation: { en: "The author says, 'I'd recommend subscribing to a service that values thorough reporting over sensationalism'.", pt: "O autor diz: 'Eu recomendaria assinar um serviço que valoriza a reportagem minuciosa em vez do sensacionalismo'." } },
        ],
      },
      quickCheck: [
        { id: "i35d-qc1", prompt: { en: "Which word describes the main title of a newspaper story?", pt: "Qual palavra descreve o título principal de uma matéria de jornal?" }, options: ["article", "headline", "report"], answer: "headline", explanation: { en: "A headline is the title of a news article.", pt: "Uma manchete é o título de um artigo de notícias." } },
        { id: "i35d-qc2", prompt: { en: "Fill in the blank: 'Compared to online news, print newspapers are often ______.'", pt: "Preencha a lacuna: 'Comparado às notícias online, jornais impressos são frequentemente ______.'" }, options: ["more instant", "less immediate", "more dynamic"], answer: "less immediate", explanation: { en: "Print newspapers usually provide updates less immediately than online news.", pt: "Jornais impressos geralmente fornecem atualizações menos imediatamente do que notícias online." } },
        { id: "i35d-qc3", prompt: { en: "If you want to suggest a specific news source, what could you say?", pt: "Se você quer sugerir uma fonte de notícias específica, o que você poderia dizer?" }, options: ["I think that source.", "I recommend that source.", "I recommend to that source."], answer: "I recommend that source.", explanation: { en: "'I recommend...' is a direct way to make a recommendation.", pt: "'I recommend...' é uma forma direta de fazer uma recomendação." } },
        { id: "i35d-qc4", prompt: { en: "What is an 'opinion piece'?", pt: "O que é um 'artigo de opinião'?" }, options: ["A factual news report.", "An article expressing personal views.", "A live television broadcast."], answer: "An article expressing personal views.", explanation: { en: "An opinion piece specifically contains the author's personal views.", pt: "Um artigo de opinião contém especificamente as opiniões pessoais do autor." } },
      ],
