      quickCheck: [
        { id: "i36d-qc1", prompt: { en: "Which expression is used to give advice?", pt: "Qual expressão é usada para dar conselhos?" }, options: ["I wonder if...", "I'd recommend...", "Tell me about..."], answer: "I'd recommend...", explanation: { en: "'I'd recommend...' is one of the expressions introduced for giving advice.", pt: "'I'd recommend...' é uma das expressões introduzidas para dar conselhos." } },
        { id: "i36d-qc2", prompt: { en: "What does 'keep up with' mean?", pt: "O que 'keep up with' significa?" }, options: ["To ignore something.", "To stay informed about something.", "To create something new."], answer: "To stay informed about something.", explanation: { en: "'Keep up with' means to stay informed or updated.", pt: "'Keep up with' significa manter-se informado ou atualizado." } },
        { id: "i36d-qc3", prompt: { en: "If something is a 'norm' in a society, what does it mean?", pt: "Se algo é uma 'norma' em uma sociedade, o que isso significa?" }, options: ["It's very unusual.", "It's a typical or expected behavior.", "It's a new invention."], answer: "It's a typical or expected behavior.", explanation: { en: "A 'norm' refers to a standard or expected behavior within a group.", pt: "Uma 'norma' refere-se a um padrão ou comportamento esperado dentro de um grupo." } },
        { id: "i36d-qc4", prompt: { en: "Which of these collocations means to adjust to a new situation?", pt: "Qual dessas colocações significa ajustar-se a uma nova situação?" }, options: ["rely on", "adapt to", "keep up with"], answer: "adapt to", explanation: { en: "'Adapt to' means to become familiar with a new situation and change behavior accordingly.", pt: "'Adapt to' significa familiarizar-se com uma nova situação e mudar o comportamento de acordo." } },
      ],
