      warmUp: { prompt: { en: "Look at these images related to business and economy. What do you see? What do you think these businesses do?", pt: "Observe estas imagens relacionadas a negócios e economia. O que você vê? O que você acha que esses negócios fazem?" }, phrases: [{ en: "This image shows a bustling market.", pt: "Esta imagem mostra um mercado movimentado." }, { en: "I think this company sells technology products.", pt: "Eu acho que esta empresa vende produtos de tecnologia." }] },
      context: {
        situation: { en: "Sarah is at a networking event. She meets David, a potential business partner. They introduce themselves and discuss their work.", pt: "Sarah está em um evento de networking. Ela conhece David, um potencial parceiro de negócios. Eles se apresentam e discutem seu trabalho." },
        dialogue: [
          { who: "Sarah", en: "Hello. Let me introduce myself. I'm Sarah Miller, a project manager at InnovateTech.", pt: "Olá. Permita-me apresentar-me. Sou Sarah Miller, gerente de projetos na InnovateTech." },
          { who: "David", en: "It's a pleasure to meet you, Sarah. I'm David Chen. I'm currently working as a business development specialist for Global Trends.", pt: "É um prazer conhecê-la, Sarah. Sou David Chen. Atualmente, trabalho como especialista em desenvolvimento de negócios para a Global Trends." },
          { who: "Sarah", en: "InnovateTech focuses on developing new tech startups. We also help with investment strategies.", pt: "A InnovateTech foca no desenvolvimento de novas startups de tecnologia. Também ajudamos com estratégias de investimento." },
          { who: "David", en: "That's interesting. Global Trends analyzes market data to predict consumer trends and optimize supply chains.", pt: "Isso é interessante. A Global Trends analisa dados de mercado para prever tendências de consumo e otimizar cadeias de suprimentos." },
          { who: "Sarah", en: "Sounds like we're in related fields. The competition in tech is tough, so strong strategy is key for growth.", pt: "Parece que estamos em áreas relacionadas. A concorrência em tecnologia é acirrada, então uma estratégia forte é fundamental para o crescimento." },
          { who: "David", en: "Absolutely. Maximizing revenue is always the goal, and understanding the market is crucial.", pt: "Com certeza. Maximizar a receita é sempre o objetivo, e entender o mercado é crucial." },
        ],
      },
      vocabulary: [
        { term: "investment", pt: "investimento", ipa: "/ɪnˈvɛstmənt/", definition: "An asset or item acquired with the goal of generating income or appreciation.", example: "The company made a significant investment in renewable energy.", examplePt: "A empresa fez um investimento significativo em energia renovável." },
        { term: "market", pt: "mercado", ipa: "/ˈmɑːrkɪt/", definition: "A place or system where goods and services are bought and sold.", example: "The real estate market is currently very competitive.", examplePt: "O mercado imobiliário está atualmente muito competitivo." },
        { term: "revenue", pt: "receita", ipa: "/ˈrɛvənuː/", definition: "The total income generated by the sale of goods or services before any expenses are deducted.", example: "Their annual revenue increased by 15% last year.", examplePt: "A receita anual deles aumentou em 15% no ano passado." },
        { term: "startup", pt: "startup", ipa: "/ˈstɑːrtʌp/", definition: "A newly established business, often technological, designed to grow rapidly.", example: "Many young entrepreneurs dream of launching a successful startup.", examplePt: "Muitos jovens empreendedores sonham em lançar uma startup de sucesso." },
        { term: "competition", pt: "concorrência", ipa: "/ˌkɑmpəˈtɪʃən/", definition: "The struggle among businesses to attract customers.", example: "The fierce competition forced the company to lower its prices.", examplePt: "A concorrência acirrada forçou a empresa a baixar seus preços." },
        { term: "growth", pt: "crescimento", ipa: "/ɡroʊθ/", definition: "The process of increasing in size, amount, or development.", example: "The company's rapid growth created many new job opportunities.", examplePt: "O rápido crescimento da empresa criou muitas novas oportunidades de emprego." },
        { term: "strategy", pt: "estratégia", ipa: "/ˈstrætədʒi/", definition: "A plan of action designed to achieve a long-term or overall aim.", example: "They developed a new marketing strategy to reach younger consumers.", examplePt: "Eles desenvolveram uma nova estratégia de marketing para alcançar consumidores mais jovens." },
        { term: "supply chain", pt: "cadeia de suprimentos", ipa: "/səˈplaɪ tʃeɪn/", definition: "The system of organizations, people, activities, information, and resources involved in moving a product or service from supplier to customer.", example: "Disruptions in the global supply chain affected many industries.", examplePt: "Interrupções na cadeia de suprimentos global afetaram muitas indústrias." },
        { term: "consumer", pt: "consumidor", ipa: "/kənˈsuːmər/", definition: "A person who buys goods and services for personal use.", example: "Modern consumers often look for eco-friendly products.", examplePt: "Consumidores modernos frequentemente procuram produtos ecologicamente corretos." },
        { term: "trend", pt: "tendência", ipa: "/trɛnd/", definition: "A general direction in which something is developing or changing.", example: "There is a growing trend towards online shopping.", examplePt: "Há uma tendência crescente para compras online." },
      ],
      expressions: [{ en: "Let me introduce myself.", pt: "Permita-me apresentar-me." }, { en: "I'm currently working as...", pt: "Atualmente, trabalho como..." }, { en: "It's a pleasure to meet you.", pt: "É um prazer conhecê-lo(a)." }],
      grammar: [
        {
          title: { en: "Linking words for consequence and summary", pt: "Conectivos de consequência e resumo" },
          examples: [{ en: "The company increased its marketing budget. As a result, sales improved significantly.", pt: "A empresa aumentou seu orçamento de marketing. Como resultado, as vendas melhoraram significativamente." }, { en: "They faced many challenges. Overall, the project was a success.", pt: "Eles enfrentaram muitos desafios. No geral, o projeto foi um sucesso." }, { en: "We discussed all the proposals. In conclusion, we decided to proceed with option B.", pt: "Discutimos todas as propostas. Em conclusão, decidimos prosseguir com a opção B." }],
          rule: { en: "Linking words such as 'as a result', 'in conclusion', and 'overall' connect ideas and help organize information. 'As a result' introduces the consequence or outcome of a previous action. 'In conclusion' is used to signal the end of a discussion or a summary of main points. 'Overall' means generally or considering everything, used to give a general statement or summary.", pt: "Conectivos como 'as a result' (como resultado), 'in conclusion' (em conclusão) e 'overall' (no geral) conectam ideias e ajudam a organizar a informação. 'As a result' introduz a consequência ou o resultado de uma ação anterior. 'In conclusion' é usado para sinalizar o fim de uma discussão ou um resumo dos pontos principais. 'Overall' significa de forma geral ou considerando tudo, usado para fazer uma afirmação geral ou um resumo." },
          mistakes: [{ en: "Using 'as a result' for contradiction instead of consequence. (Incorrect: He worked hard, as a result, he failed.)", pt: "Usar 'as a result' para contradição em vez de consequência. (Incorreto: Ele trabalhou duro, como resultado, ele falhou.)" }, { en: "Confusing 'overall' with 'specifically'. (Incorrect: Overall, the specific problem was found.)", pt: "Confundir 'overall' com 'especificamente'. (Incorreto: No geral, o problema específico foi encontrado.)" }],
        },
      ],
