          phrases: [{ en: "I've just been to the new library.", pt: "Acabei de ir à nova biblioteca." }, { en: "I haven't visited the art museum yet.", pt: "Eu ainda não visitei o museu de arte." }, { en: "It has been important because I've learned a lot.", pt: "Tem sido importante porque eu aprendi muito." }],
