      lessonReview: { summary: { en: "In this unit, we have explored various city places and discussed experiences using the Present Perfect. We've also learned how to agree and disagree politely in conversations.", pt: "Nesta unidade, exploramos vários lugares da cidade e discutimos experiências usando o Present Perfect. Também aprendemos a concordar e discordar educadamente em conversas." }, canDo: [{ en: "Talk about experiences in different city places using the Present Perfect.", pt: "Falar sobre experiências em diferentes lugares da cidade usando o Present Perfect." }, { en: "Express agreement and disagreement using appropriate phrases.", pt: "Expressar concordância e discordância usando frases apropriadas." }, { en: "Plan activities for a city tour, describing past actions and present results.", pt: "Planejar atividades para um tour pela cidade, descrevendo ações passadas e resultados presentes." }], next: { en: "In the next unit, we will continue practicing the Present Perfect with 'for' and 'since' and explore vocabulary related to daily routines.", pt: "Na próxima unidade, continuaremos praticando o Present Perfect com 'for' e 'since' e exploraremos vocabulário relacionado a rotinas diárias." } },
